#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int f;
} Node;

void swap(Node *a, Node *b) {
    Node t = *a;
    *a = *b;
    *b = t;
}

void down(Node heap[], int size, int i) {
    int smallest = i;
    int l = 2 * i + 1;
    int r = 2 * i + 2;

    if (l < size && heap[l].val < heap[smallest].val)
        smallest = l;
    if (r < size && heap[r].val < heap[smallest].val)
        smallest = r;

    if (smallest != i) {
        swap(&heap[i], &heap[smallest]);
        down(heap, size, smallest);
    }
}

void buildHeap(Node heap[], int size) {
    for (int i = size / 2 - 1; i >= 0; i--) {
        down(heap, size, i);
    }
}

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (y > x) - (y < x);
}

