    int N, M;
    scanf("%d %d", &N, &M);

    int *T = (int *)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
    }

    int *F = (int *)malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) {
        scanf("%d", &F[i]);
    }

    if (N <= M) {
        printf("0\n");
        free(T);
        free(F);
        return 0;
    }

    qsort(T, N, sizeof(int), cmp);

    Node *heap = (Node *)malloc(M * sizeof(Node));
    for (int i = 0; i < M; i++) {
        heap[i].val = F[i];
        heap[i].f = F[i];
    }
    buildHeap(heap, M);

    long long ans = 0;
    int need = N - M;

    for (int k = 0; k < need; k++) {
        ans += (long long)T[M + k] * heap[0].val;
        heap[0].val += heap[0].f;
        down(heap, M, 0);
    }

    printf("%lld\n", ans);

    free(T);
    free(F);
    free(heap);
    return 0;
}
