#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int f;
} Node;

int cmp_desc(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

void sift_down(Node *heap, int size, int i) {
    while (1) {
        int l = i * 2 + 1;
        int r = i * 2 + 2;
        int smallest = i;

        if (l < size && heap[l].val < heap[smallest].val) smallest = l;
        if (r < size && heap[r].val < heap[smallest].val) smallest = r;

        if (smallest == i) break;

        Node tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
}

int main() {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long *T = (long long *)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) {
        scanf("%lld", &T[i]);
    }

    qsort(T, N, sizeof(long long), cmp_desc);

    Node *heap = (Node *)malloc(M * sizeof(Node));
    for (int i = 0; i < M; i++) {
        int f;
        scanf("%d", &f);
        heap[i].val = 0;
        heap[i].f = f;
    }

    long long ans = 0;

    for (int i = 0; i < N; i++) {
        long long v = heap[0].val;
        ans += v * T[i];

        int f = heap[0].f;
        heap[0].val = v + f;

        sift_down(heap, M, 0);
    }

    printf("%lld\n", ans);

    free(T);
    free(heap);

    return 0;
}
